WITH temp_view_0 AS (
SELECT /*+ materialize */ F0_0."AGG_GB_ARG1" AS SUPPLIER_NO, F0_0."AGGR_0" AS TOTAL_REVENUE, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, DENSE_RANK() OVER ( ORDER BY F0_0."AGG_GB_ARG1") AS _RESULT_TID, ROW_NUMBER() OVER (PARTITION BY F0_0."AGG_GB_ARG1" ORDER BY F0_0."AGG_GB_ARG1") AS _SETPROV_DUP_COUNT
FROM (
SELECT (F0_0.L_EXTENDEDPRICE * (1 - F0_0.L_DISCOUNT)) AS "AGG_GB_ARG0", F0_0.L_SUPPKEY AS "AGG_GB_ARG1", F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, SUM((F0_0.L_EXTENDEDPRICE * (1 - F0_0.L_DISCOUNT))) OVER (PARTITION BY F0_0.L_SUPPKEY) AS "AGGR_0"
FROM (
SELECT F0_0.L_SUPPKEY AS L_SUPPKEY, F0_0.L_EXTENDEDPRICE AS L_EXTENDEDPRICE, F0_0.L_DISCOUNT AS L_DISCOUNT, F0_0.L_SHIPDATE AS L_SHIPDATE, F0_0.L_ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.L_LINENUMBER AS PROV_LINEITEM_L__LINENUMBER
FROM LINEITEM F0_0) F0_0
WHERE ((F0_0.L_SHIPDATE >= ('1996-01-01')::DATE) AND (F0_0.L_SHIPDATE < (('1996-01-01')::DATE + ('3 month')::INTERVAL)))) F0_0)
SELECT F0_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_0."PROV_LINEITEM_1_L__LINENUMBER" AS "PROV_LINEITEM_1_L__LINENUMBER"
FROM (
SELECT F0_0.S_SUPPKEY AS S_SUPPKEY, F0_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_0."PROV_LINEITEM_1_L__LINENUMBER" AS "PROV_LINEITEM_1_L__LINENUMBER"
FROM (
SELECT F0_0.S_SUPPKEY AS S_SUPPKEY, F0_0.SUPPLIER_NO AS SUPPLIER_NO, F0_0.TOTAL_REVENUE AS TOTAL_REVENUE, F1_0."NESTING_EVAL_1" AS "NESTING_EVAL_1", F0_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F1_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F1_0."PROV_LINEITEM_1_L__LINENUMBER" AS "PROV_LINEITEM_1_L__LINENUMBER"
FROM (
SELECT F0_0.S_SUPPKEY AS S_SUPPKEY, F1_0.SUPPLIER_NO AS SUPPLIER_NO, F1_0.TOTAL_REVENUE AS TOTAL_REVENUE, F0_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F1_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F1_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER
FROM ((
SELECT F0_0.S_SUPPKEY AS S_SUPPKEY, F0_0.S_SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY
FROM SUPPLIER F0_0) F0_0 CROSS JOIN (SELECT * FROM temp_view_0) F1_0)) F0_0, LATERAL (
SELECT F0_1."AGGR_0" AS "NESTING_EVAL_1", F0_1."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_1."PROV_LINEITEM_1_L__LINENUMBER" AS "PROV_LINEITEM_1_L__LINENUMBER"
FROM (
SELECT F0_1.TOTAL_REVENUE AS TOTAL_REVENUE, F0_1."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_1."PROV_LINEITEM_1_L__LINENUMBER" AS "PROV_LINEITEM_1_L__LINENUMBER", F0_1._RESULT_TID AS _RESULT_TID, F0_1._SETPROV_DUP_COUNT AS _SETPROV_DUP_COUNT, MAX((CASE  WHEN (1 = F0_1._SETPROV_DUP_COUNT) THEN F0_1.TOTAL_REVENUE ELSE NULL END)) OVER () AS "AGGR_0", COUNT(1) OVER () AS __DUMMY_CNT
FROM ((
SELECT F0_1.TOTAL_REVENUE AS TOTAL_REVENUE, F0_1.PROV_LINEITEM_L__ORDERKEY AS "PROV_LINEITEM_1_L__ORDERKEY", F0_1.PROV_LINEITEM_L__LINENUMBER AS "PROV_LINEITEM_1_L__LINENUMBER", F0_1._RESULT_TID AS _RESULT_TID, F0_1._SETPROV_DUP_COUNT AS _SETPROV_DUP_COUNT
FROM (SELECT * FROM temp_view_0) F0_1 UNION ALL (SELECT NULL AS TOTAL_REVENUE, NULL AS "PROV_LINEITEM_1_L__ORDERKEY", NULL AS "PROV_LINEITEM_1_L__LINENUMBER", -1 AS _RESULT_TID, NULL AS _SETPROV_DUP_COUNT))) F0_1) F0_1
WHERE ((F0_1.__DUMMY_CNT = 1) OR (F0_1._RESULT_TID <> -1))) F1_0) F0_0
WHERE ((F0_0.S_SUPPKEY = F0_0.SUPPLIER_NO) AND (F0_0.TOTAL_REVENUE = F0_0."NESTING_EVAL_1"))
ORDER BY S_SUPPKEY ASC NULLS LAST) F0_0;


